-- OWNER-APPROVED PREPARATION ONLY. Deployment remains gated.
-- Generated by scripts/prepare-employee-history-reads.mts. No member changes.
begin;
set local lock_timeout='2s';
set local statement_timeout='8s';
alter table staff_workflow_private.settings add column history_reads_enabled boolean not null default false;
create function staff_workflow_private.history_reads_actor() returns void
language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or auth.jwt()->>'role' is distinct from 'doji_employee'
  or auth.jwt()->>'aal' is distinct from 'aal2' or not public.admin_user_has_permission('portal.session') then
  raise exception using errcode='42501',message='Employee MFA required';end if;
 if not exists(select 1 from staff_workflow_private.settings where singleton and enabled and history_reads_enabled) then
  raise exception using errcode='55000',message='Employee history reads disabled';end if;
end$$;
create function public.get_admin_personal_work_page_v1(
 p_kind text default 'all',p_state text default 'open',p_limit integer default 25,
 p_after_at timestamptz default null,p_after_key text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; mod boolean; legal boolean; ideas boolean; business boolean; privacy boolean;begin
 perform staff_workflow_private.extended_actor();
 perform staff_workflow_private.history_reads_actor();
 if p_kind is null or p_kind not in ('all','report','appeal','suggestion','business_application','external_intake','business_privacy')
  or p_state is null or p_state not in ('all','open','completed') or p_limit is null or p_limit not between 1 and 25
  or (p_after_at is null)<>(p_after_key is null) or (p_after_at is not null and not isfinite(p_after_at))
  or (p_after_key is not null and p_after_key !~ '^(report|appeal|suggestion|business_application|external_intake|business_privacy):[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then
  raise exception using errcode='22023',message='Invalid staff inbox parameters';end if;
 mod:=public.admin_user_has_permission('moderation.read');legal:=public.admin_user_has_permission('legal.read');
 ideas:=public.admin_user_has_permission('operations.read');
 business:=public.admin_user_has_permission('business.read') and exists(select 1 from business_private.settings where enabled and application_terms_version is not null and privacy_version is not null);
 privacy:=legal and public.admin_user_has_permission('admin.manage') and exists(select 1 from business_private.privacy_settings where enabled);
 with sources as (
  (select 'report'::text kind,r.id,r.created_at at,t.assigned_to,'Content report'::text subject,case when r.status='pending' then 'ready' else 'closed' end work_state,
    r.created_at+interval '24 hours' due_at,'existing_report'::text ownership_model
   from public.reports r left join public.admin_report_triage t on t.report_id=r.id
   where mod and p_kind in ('all','report') and (p_state='all' or (r.status='pending')=(p_state='open')) and (coalesce(t.queue,'moderation')<>'restricted_safety' or legal)
    and t.assigned_to=auth.uid()
    and (p_after_at is null or (r.created_at,'report:'||r.id)>(p_after_at,p_after_key)) order by r.created_at,r.id limit p_limit+1)
  union all
  (select 'appeal',a.id,a.submitted_at,o.assigned_to,'Moderation appeal',case when a.status='pending' then 'ready' else 'closed' end,null::timestamptz,'staff_workflow'
   from public.moderation_appeals a left join staff_workflow_private.ownership o on o.kind='appeal' and o.case_id=a.id
   where mod and p_kind in ('all','appeal') and (p_state='all' or (a.status='pending')=(p_state='open')) and (legal or not staff_workflow_private.appeal_restricted(a.id))
     and o.assigned_to=auth.uid()
    and (p_after_at is null or (a.submitted_at,'appeal:'||a.id)>(p_after_at,p_after_key)) order by a.submitted_at,a.id limit p_limit+1)
  union all
  (select 'suggestion',s.id,s.created_at,o.assigned_to,left(s.body,120),case when s.status='pending' then 'ready' else 'closed' end,null::timestamptz,'staff_workflow'
   from public.challenge_suggestions s left join staff_workflow_private.ownership o on o.kind='suggestion' and o.case_id=s.id
   where ideas and p_kind in ('all','suggestion') and (p_state='all' or (s.status='pending')=(p_state='open')) 
    and o.assigned_to=auth.uid()
    and (p_after_at is null or (s.created_at,'suggestion:'||s.id)>(p_after_at,p_after_key)) order by s.created_at,s.id limit p_limit+1)
  union all
  (select 'business_application',a.id,a.created_at,o.assigned_to,coalesce(nullif(left(s.details->>'brand_name',120),''),'Business application'),
    case when a.state in ('approved','declined') then 'closed' when a.state='changes_requested' then 'waiting' else 'ready' end,null::timestamptz,'staff_workflow'
   from business_private.applications a left join staff_workflow_private.ownership o on o.kind='business_application' and o.case_id=a.id
   left join business_private.submissions s on s.application_id=a.id and s.submission=a.submission
   where business and p_kind in ('all','business_application') and a.state in ('pending','changes_requested','approved','declined')
    and (p_state='all' or (a.state in ('pending','changes_requested'))=(p_state='open'))
    and o.assigned_to=auth.uid()
    and (p_after_at is null or (a.created_at,'business_application:'||a.id)>(p_after_at,p_after_key)) order by a.created_at,a.id limit p_limit+1)
  union all
  (select 'external_intake',c.id,c.received_at,c.assigned_to,'External removal request',
    case when c.closed_at is not null then 'closed' when c.state='needs_information' then 'waiting' else 'ready' end,c.deadline_at,'existing_intake'
   from public.safety_removal_cases c where mod and p_kind in ('all','external_intake') 
    and (c.queue='moderation' or legal)
    and (p_state='all' or (c.closed_at is null)=(p_state='open'))
    and c.assigned_to=auth.uid()
    and (p_after_at is null or (c.received_at,'external_intake:'||c.id)>(p_after_at,p_after_key)) order by c.received_at,c.id limit p_limit+1)
  union all
  (select 'business_privacy',c.id,c.received_at,o.assigned_to,'Business privacy request',
    case when c.state in ('completed','denied') then 'closed' when c.state='executing' then 'waiting' else 'ready' end,c.due_at,'staff_workflow'
   from business_private.privacy_cases c left join staff_workflow_private.ownership o on o.kind='business_privacy' and o.case_id=c.id
   where privacy and p_kind in ('all','business_privacy') 
    and (p_state='all' or (c.state not in ('completed','denied'))=(p_state='open'))
    and o.assigned_to=auth.uid()
    and (p_after_at is null or (c.received_at,'business_privacy:'||c.id)>(p_after_at,p_after_key)) order by c.received_at,c.id limit p_limit+1)
 ), bounded as (select *,kind||':'||id key from sources order by at,kind||':'||id limit p_limit+1),
 page as (select * from bounded order by at,key limit p_limit)
 select jsonb_build_object('scope','personal_work_v1','filter',p_state,'order','oldest_first',
  'items',coalesce((select jsonb_agg(to_jsonb(p)||case when work_state='closed' then jsonb_build_object('due_at',null) else '{}'::jsonb end order by at,key) from page p),'[]'),
  'next_cursor',case when (select count(*) from bounded)>p_limit then (select jsonb_build_object('at',at,'key',key) from page order by at desc,key desc limit 1) else null end,
  'authorized_queues',to_jsonb(array_remove(array[case when mod then 'report' end,case when mod then 'appeal' end,
    case when mod then 'external_intake' end,case when ideas then 'suggestion' end,
    case when business then 'business_application' end,case when privacy then 'business_privacy' end],null))) into result;
 return result;
end$$;
-- Display-state filtering happens before the limit; never filter a loaded page.
-- Same precedence as admin_editorial_item_v1, including unmanaged legacy rows.
create function public.get_admin_announcement_lifecycle_page_v1(
 p_filter text default 'active',p_limit integer default 25,
 p_before_at timestamptz default null,p_before_id uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare ids uuid[]; v_id uuid; item jsonb; items jsonb:='[]'; cursor jsonb:=null; n integer:=0;
begin
 perform public.admin_editorial_authorize_v1(false);
 perform staff_workflow_private.history_reads_actor();
 if p_filter is null or p_filter not in ('active','all','draft','live','scheduled','expired','cancelled','disabled')
  or p_limit is null or p_limit not between 1 and 25
  or (p_before_at is null)<>(p_before_id is null)
  or (p_before_at is not null and not isfinite(p_before_at)) then
  raise exception using errcode='22023',message='Invalid announcement lifecycle page';end if;
 select array_agg(x.id order by x.created_at desc,x.id desc) into ids from (
  select a.id,a.created_at from public.app_announcements a
  left join public.admin_announcement_state s on s.announcement_id=a.id
  cross join lateral (select case when s.state in ('draft','cancelled') then s.state
   when not a.enabled then 'disabled' when a.ends_at<=now() then 'expired'
   when a.starts_at>now() then 'scheduled' else 'live' end display_state) d
  where (p_filter='all' or d.display_state=p_filter
   or (p_filter='active' and d.display_state in ('draft','live','scheduled')))
   and (p_before_at is null or (a.created_at,a.id)<(p_before_at,p_before_id))
  order by a.created_at desc,a.id desc limit p_limit+1
 ) x;
 foreach v_id in array coalesce(ids,'{}'::uuid[]) loop
  n:=n+1;
  if n>p_limit then cursor:=jsonb_build_object('at',item->>'created_at','id',item->>'id');exit;end if;
  item:=public.admin_editorial_item_v1('announcements',v_id);
  items:=items||jsonb_build_array(item-'body'-'options'-'admin_note');
 end loop;
 return jsonb_build_object('scope','announcement_lifecycle_v1','filter',p_filter,
  'items',items,'next_cursor',cursor,'can_write',public.admin_user_has_permission('admin.manage'));
end$$;

revoke all on function staff_workflow_private.history_reads_actor(),
 public.get_admin_personal_work_page_v1(text,text,integer,timestamptz,text),
 public.get_admin_announcement_lifecycle_page_v1(text,integer,timestamptz,uuid)
 from public,anon,authenticated,service_role,doji_employee,doji_business,doji_employee_application;
grant execute on function public.get_admin_personal_work_page_v1(text,text,integer,timestamptz,text),
 public.get_admin_announcement_lifecycle_page_v1(text,integer,timestamptz,uuid) to doji_employee;
commit;
